{
  "technical_and_design_decisions": [
    "Use YARN ResourceManager REST API for negotiation and deployment instead of legacy Hadoop RPC, aligning with cloud-native and REST-based instrumentation.",
    "Define a deployment manifest (YAML/JSON) stored in HDFS that describes target locations and assets for automatic YARN app deployment.",
    "Leverage Spring Boot's JarLauncher and LaunchedURLClassLoader for module launching and adding external JARs, eliminating custom duplicate launcher code.",
    "Make the deployer asynchronous using Spring's TaskExecutor/@Async and an internal task queue, allowing the shell to return immediately and YARN tasks to be queued.",
    "Support multiple YARN app instances by mapping deployment properties (e.g., module.*.yarn.app.name, queues, priorities, memory/cpu) to separate YARN application contexts.",
    "Implement a unified external library resolver that resolves Maven/LOCAL dependencies and adds them to the Boot loader classpath for all modules.",
    "Maintain backward compatibility with existing Spring Cloud Data YARN deployment flows."
  ],
  "assumptions": [
    "Existing Spring Cloud Data YARN codebase, build system, and tests are available and building locally.",
    "A test YARN cluster (or pseudo-distributed mode) is available for integration testing; cluster setup time is excluded from estimates.",
    "Development uses Java 17+ and Spring Boot 3.x (Spring Framework 6), where Boot's JarLauncher API is available and compatible.",
    "All work (analysis, dev, test, docs) is performed by a single experienced developer; effort excludes meetings, code reviews by others, and elapsed time.",
    "The deployment property syntax shown in U3 is authoritative and will be handled by extending existing property parsers.",
    "No separate UI work is needed beyond making the shell command return quickly.",
    "Documentation required is limited to the reference docs/tests in U7 plus inline Javadoc; broader user guide updates are not separately estimated."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Requirements analysis and technical design",
      "activity_description": "Analyze existing Spring Cloud Data YARN code, design manifest schema, REST client approach, async deployer, deployment property handling, and Boot loader integration covering all user stories.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Automatic YARN app deployment to HDFS (U1)",
      "activity_description": "Implement manifest model and logic to upload YARN app assets to HDFS automatically so xd-admin can orchestrate deployment using the manifest.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "ResourceManager REST API integration (U2)",
      "activity_description": "Build REST client to YARN ResourceManager to negotiate deployment, deploy modules by groups, set appType=CLOUDDATA and appName=spring-cloud-data-yarn-app, and start app instances automatically.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "Multiple app instances and deployment properties (U3)",
      "activity_description": "Extend deployer to support per-module yarn.app.name, different queues/priorities, and runtime resource (memory/CPU) reservation via deployment properties.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "Asynchronous deployer with task queue (U4)",
      "activity_description": "Refactor deployer to return control to shell quickly, queue deploy operations as YARN tasks, and handle asynchronous status updates.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Spike: Resolve and add module JARs to Boot loader (U5)",
      "activity_description": "Research and prototype approach to resolve module dependent JARs and add them to Spring Boot loader classpath for OOTB modules.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Refactor ModuleLauncher to Boot JarLauncher (U6)",
      "activity_description": "Replace custom ModuleLauncher functionality with Spring Boot's JarLauncher API to remove duplicate code and align contracts.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "Uniform external library support (U8)",
      "activity_description": "Implement support to add external libraries consistently for modules, building on the Boot loader JAR resolution approach.",
      "most_likely_effort": 18
    },
    {
      "activity_id": "ACT-9",
      "activity_name": "Documentation and test cases for JAR/Boot loader (U7)",
      "activity_description": "Complete reference documentation and unit/integration test cases for resolving and adding JARs to Boot loader to guide porting of modules with external dependencies.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-10",
      "activity_name": "Integration testing and verification",
      "activity_description": "Perform end-to-end integration testing of HDFS deploy, REST group deploy, multiple instances, async deployer, and external libraries; fix defects and verify build.",
      "most_likely_effort": 24
    }
  ],
  "reported_total": {
    "most_likely_effort": 202
  }
}

